-- Guarded cleanup of inert legacy resource child pools, batch 05.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (1897,1898,1900,1902,1903,1904,1907,1909,1910,1911,1912,1915,1916,1917,1919,1920,1921,1922,1923,1924,1927,1928,1930,1931,1932,1933,1934,1936,1943,1957,1969,1972,1975,1983,1985,1993,1998,2000,2001,2010,2015,2019,2023,2026,2031,2038,2042,2043,2047,2049) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (1897,1898,1900,1902,1903,1904,1907,1909,1910,1911,1912,1915,1916,1917,1919,1920,1921,1922,1923,1924,1927,1928,1930,1931,1932,1933,1934,1936,1943,1957,1969,1972,1975,1983,1985,1993,1998,2000,2001,2010,2015,2019,2023,2026,2031,2038,2042,2043,2047,2049) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

